pub fn replace_with_ids(
    &mut self,
    lang: &str,
    request: Replacement,
    mut generator: impl FnMut() -> String,
) -> Result<Value> {
    language(lang)?;
    if request.ids.is_empty() && request.replacements.is_empty() {
        return Err(invalid("empty replacement"));
    }
    unique(&request.ids)?;
    let reviews = request
        .replacements
        .iter()
        .map(|e| e.review.as_ref().map(|r| self.resolve(r)).transpose())
        .collect::<Result<Vec<_>>>()?;
    let timestamp = self.now.to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    let old = active_records(&tx, lang, &request.ids)?;
    let retired: Vec<Value> = old
        .iter()
        .map(|r| json!({"id":r.id,"previous_review_on":r.review_on,"previous_pinned":r.pinned}))
        .collect();
    let mut created = Vec::new();
    let mut unscheduled = Vec::new();
    for (entry, review) in request.replacements.iter().zip(reviews.iter()) {
        let id = loop {
            let id = generator();
            if id.len() < 6
                || !id
                    .bytes()
                    .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
            {
                return Err(invalid("invalid generated ID"));
            }
            if !tx.query_row(
                "SELECT EXISTS(SELECT 1 FROM records WHERE id=?1)",
                [&id],
                |r| r.get::<_, bool>(0),
            )? {
                break id;
            }
        };
        tx.execute(
            "INSERT INTO records VALUES (?1,?2,?3,?4,?5,?6,?7,NULL)",
            params![
                id,
                lang,
                timestamp,
                json!(request.ids).to_string(),
                entry.content.to_string(),
                entry.pinned,
                review
            ],
        )?;
        if review.is_none() {
            unscheduled.push(id.clone());
        }
        created.push(id);
    }
    for id in &request.ids {
        tx.execute(
            "UPDATE records SET retired_at=?1,review_on=NULL WHERE id=?2",
            params![timestamp, id],
        )?;
    }
    tx.execute(
        "INSERT INTO events VALUES (?1,?2,?3,?4)",
        params![
            timestamp,
            json!(request.ids).to_string(),
            json!(created).to_string(),
            json!(retired).to_string()
        ],
    )?;
    tx.commit()?;
    let mut reminders = Vec::new();
    if old.iter().any(|r| r.review_on.is_some()) && !unscheduled.is_empty() {
        reminders.push("Choose review dates for unscheduled successors.");
    }
    if old.iter().any(|r| r.pinned) && !created.is_empty() {
        reminders.push("Consider pinning successor records.");
    }
    Ok(
        json!({"created":created,"retired":retired,"needs_review_schedule":unscheduled,"reminders":reminders}),
    )
}

pub fn context(&self, lang: Option<&str>, limit: usize) -> Result<Value> {
    check_limit(limit)?;
    if let Some(lang) = lang {
        language(lang)?;
    }
    let mut stmt = self
        .conn
        .prepare("SELECT DISTINCT language FROM records ORDER BY language")?;
    let languages = stmt
        .query_map([], |r| r.get::<_, String>(0))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let mut result = json!({"now":self.now.to_rfc3339_opts(chrono::SecondsFormat::Nanos,true),"today":self.today().to_string(),"timezone":self.timezone.to_string(),"languages":languages});
    if let Some(lang) = lang {
        let mut pinned = self
            .all(lang)?
            .into_iter()
            .filter(|r| r.pinned && r.retired_at.is_none())
            .collect::<Vec<_>>();
        pinned.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.id.cmp(&b.id)));
        result["language"] = json!(lang);
        result["pinned"] = json!(pinned);
        result["due"] = self.list(
            lang,
            Filters {
                due: true,
                ..Default::default()
            },
            limit,
            None,
        )?;
        result["recent"] = self.list(lang, Filters::default(), limit, None)?;
    }
    Ok(result)
}

fn read_record(conn: &Connection, lang: &str, id: &str) -> Result<Record> {
    let r = conn.query_row("SELECT id,language,created_at,predecessors,content,pinned,review_on,retired_at FROM records WHERE id=?1 AND language=?2",params![id,lang], |r| {
        let predecessors: String = r.get(3)?; let content: String = r.get(4)?;
        Ok((Record{id:r.get(0)?,language:r.get(1)?,created_at:r.get(2)?,replaces:Vec::new(),content:Value::Null,pinned:r.get(5)?,review_on:r.get(6)?,retired_at:r.get(7)?},predecessors,content))
    });
    match r {
        Ok((mut record, predecessors, content)) => {
            record.replaces = serde_json::from_str(&predecessors)
                .map_err(|_| error("database_invalid", "invalid stored predecessors"))?;
            record.content = parse_content(&content)
                .map_err(|_| error("database_invalid", "invalid stored content"))?;
            Ok(record)
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => Err(error(
            "record_missing",
            format!("record {id} not found in selected language"),
        )),
        Err(e) => Err(e.into()),
    }
}

fn json_roundtrip_scope_and_collision() {
    let (_dir, mut db) = setup("UTC");
    assert!(db.context(Some(""), 20).is_err());
    assert!(db.list("", Filters::default(), 20, None).is_err());
    assert_eq!(
        db.list("empty", Filters::default(), 20, None).unwrap()["records"],
        json!([])
    );
    let values = vec![
        Value::Null,
        json!(true),
        json!(42),
        json!(2.5),
        json!("πήγα"),
        json!([1, null]),
        json!({"kind":"practice","related_to":["nonexistent"],"z":{"b":2,"a":1}}),
    ];
    for v in values {
        let id = add(&mut db, "el", v.clone());
        assert!(
            id.len() >= 6
                && id
                    .bytes()
                    .all(|x| x.is_ascii_hexdigit() && !x.is_ascii_uppercase())
        );
        let r = record(&db, "el", &id);
        assert_eq!(r["content"], v);
        assert_eq!(r["pinned"], false);
        assert!(r["review_on"].is_null());
        assert_eq!(r["created_at"], "2026-10-17T12:00:00.000000000Z");
        assert_eq!(r.as_object().unwrap().len(), 8);
        assert_eq!(
            db.get("EL", std::slice::from_ref(&id)).unwrap_err().code,
            "record_missing"
        );
    }
    let mut ids = ["abcdef", "abcdef", "123456"].into_iter();
    let a = db
        .replace_with_ids(
            "EL",
            request(json!({"ids":[],"replacements":[{"content":null},{"content":false}]})),
            || ids.next().unwrap().into(),
        )
        .unwrap();
    assert_eq!(a["created"], json!(["abcdef", "123456"]));
    db.replace("EL", request(json!({"ids":["abcdef"],"replacements":[]})))
        .unwrap();
    let mut ids = ["abcdef", "fedcba"].into_iter();
    assert_eq!(
        db.replace_with_ids(
            "EL",
            request(json!({"ids":[],"replacements":[{"content":null}]})),
            || ids.next().unwrap().into()
        )
        .unwrap()["created"],
        json!(["fedcba"])
    );
    assert_eq!(
        db.context(None, 20).unwrap()["languages"],
        json!(["EL", "el"])
    );
}

fn scope_context_empty_and_events_preserve_handoff() {
    let (dir, mut db) = setup("UTC");
    let foreign=db.replace("fr",request(json!({"ids":[],"replacements":[{"content":"secret","pinned":true,"review":{"in_days":0}}]}))).unwrap()["created"][0].as_str().unwrap().to_owned();
    let empty = db.context(Some("el"), 20).unwrap();
    for section in ["recent", "due"] {
        assert_eq!(empty[section]["records"], json!([]));
        assert!(empty[section]["next_cursor"].is_null());
    }
    assert_eq!(empty["pinned"], json!([]));
    assert_eq!(
        db.list("el", Filters::default(), 20, None).unwrap()["records"],
        json!([])
    );
    let own = add(&mut db, "el", json!("local"));
    let before = record(&db, "fr", &foreign);
    assert_eq!(
        db.replace(
            "el",
            request(json!({"ids":[own,foreign],"replacements":[{"content":null}]}))
        )
        .unwrap_err()
        .code,
        "record_missing"
    );
    assert_eq!(record(&db, "fr", &foreign), before);
    assert_eq!(record(&db, "el", &own)["retired_at"], Value::Null);
    db.replace("fr", request(json!({"ids":[foreign],"replacements":[]})))
        .unwrap();
    let c = rusqlite::Connection::open(dir.path().join("db")).unwrap();
    let (timestamp, retired): (String, String) = c
        .query_row(
            "SELECT timestamp,retired FROM events ORDER BY rowid DESC LIMIT 1",
            [],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .unwrap();
    assert_eq!(timestamp, "2026-10-17T12:00:00.000000000Z");
    assert_eq!(
        serde_json::from_str::<Value>(&retired).unwrap(),
        json!([{"id":foreign,"previous_pinned":true,"previous_review_on":"2026-10-17"}])
    );
    assert_eq!(
        db.context(None, 20).unwrap()["languages"],
        json!(["el", "fr"])
    );
}

use chrono::{DateTime, Utc};
use language_lab::{Database, Filters, Replacement, Review};
use serde_json::{json, Value};
use tempfile::TempDir;
fn instant(s: &str) -> DateTime<Utc> {
    s.parse().unwrap()
}
const NOW: &str = "2026-10-17T12:00:00Z";
fn setup(zone: &str) -> (TempDir, Database) {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    Database::init(&p, zone).unwrap();
    let db = Database::open(&p, instant(NOW)).unwrap();
    (dir, db)
}
fn request(v: Value) -> Replacement {
    serde_json::from_value(v).unwrap()
}
fn add(db: &mut Database, lang: &str, content: Value) -> String {
    db.replace(
        lang,
        request(json!({"ids":[],"replacements":[{"content":content}]})),
    )
    .unwrap()["created"][0]
        .as_str()
        .unwrap()
        .into()
}
fn record(db: &Database, lang: &str, id: &str) -> Value {
    db.get(lang, &[id.into()]).unwrap()["records"][0].clone()
}
fn review(days: u64) -> Option<Review> {
    Some(Review {
        in_days: Some(days),
        on: None,
    })
}
